tool_input.command:
curl -X POST "http://127.0.0.1:8000/api/v1/workflows/execute" \
  -H "Content-Type: application/json" \
  -H "X-Correlation-ID: test-execution-$(date +%s)" \
  -d '{
    "definition": {
        "id": "preview_workflow",
        "name": "Canvas Workflow",
        "description": "Workflow generated from visual canvas designer",
        "nodes": [
            {
                "id": "node_2g8p91ofc",
                "type": "start",
                "name": "Start",
                "alias": "start",
                "config": {
                    "name": "Start",
                    "description": "Start workflow execution"
                },
                "next": [
                    "node_qhayi7wlf"
                ],
                "dependencies": []
            },
            {
                "id": "node_qhayi7wlf",
                "type": "agent",
                "name": "Agent",
                "alias": "agent",
                "config": {
                    "provider": "azure_openai",
                    "model": "gpt-35-turbo",
                    "prompt": "You are a helpful assistant. User request: ${workflow.input.user_request}. provide weather details for the user request",
                    "temperature": 0.7,
                    "max_tokens": 500,
                    "timeout": 60
                },
                "next": [
                    "node_yd9t0xmbw"
                ],
                "dependencies": [
                    "node_2g8p91ofc"
                ]
            },
            {
                "id": "node_yd9t0xmbw",
                "type": "end",
                "name": "End",
                "alias": "end",
                "config": {
                    "name": "End",
                    "description": "End workflow execution",
                    "collect_outputs": true
                },
                "next": [],
                "dependencies": [
                    "node_qhayi7wlf"
                ]
            }
        ]
    },
    "input_data": {
        "user_request": "provide me weather for bangalore"
    }
}' \
  --connect-timeout 10 \
  --max-time 120
